from collections import deque,defaultdict
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==4 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  for p in q:
   cells.append(p)
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    nr,nc=p[0]+dr,p[1]+dc
    if 0<=nr<R and 0<=nc<C and (nr,nc) not in seen and grid[nr][nc]==col:
     seen.add((nr,nc));q.append((nr,nc))
  comps.append((col,cells))
def norm(cells):
 mr=min(r for r,c in cells);mc=min(c for r,c in cells)
 return tuple(sorted((r-mr,c-mc) for r,c in cells))
for i,(co,cs) in enumerate(comps):
 print(i,'color',co,'n',len(cs),'bbox',(min(r for r,c in cs),min(c for r,c in cs),max(r for r,c in cs),max(c for r,c in cs)),'shape',norm(cs))
